      card.innerHTML=`<div class="domains-table-wrap"><table class="domains-table"><thead><tr><th>Server</th><th>Provider</th><th>Hostname</th><th>Provisioning</th><th>Public check</th></tr></thead><tbody>${rows.map(row=>{const probe=row.probe||{},provider=row.provider==='cloudflare'?'Cloudflare Tunnel':'Nginx Proxy Manager',status=row.delete_pending?'Removing':row.error_code==='cf_conflict'?'DNS conflict':row.error_code==='cf_target'?'Target unavailable':row.error_code==='provider_error'?'Provider error':!row.provider_enabled?'Provider off':row.provisioned?'Provisioned':'Waiting',tone=row.error_code?'bad':row.provisioned?'good':'muted',probeLabel=probe.reachable?`HTTP ${probe.status_code}`:'Unreachable',probeTone=probe.reachable?(probe.status_code>=500?'bad':'good'):'muted';return `<tr><td><b>${esc(row.server_name)}</b></td><td><span class="domain-provider">${esc(provider)}</span>${row.route_id?`<small class="domain-note">Additional · ${row.port_name?`port ${esc(row.port_name)}`:'automatic TCP port'}</small>`:''}${row.last_error?`<small class="domain-error">${esc(row.last_error)}</small>`:''}</td><td><code>${esc(row.hostname)}</code></td><td><span class="status-badge ${tone}"><i></i>${esc(status)}</span></td><td><span class="status-badge ${probeTone}"><i></i>${esc(probeLabel)}</span>${probe.self_signed?'<small class="domain-note">Untrusted certificate</small>':''}${probe.warning?`<small class="domain-note">${esc(probe.warning)}</small>`:''}${probe.error?`<small class="domain-error">${esc(probe.error)}</small>`:''}</td></tr>`}).join('')}</tbody></table></div><div class="domains-footnote">Checks prefer HTTPS, do not follow redirects, and reject private or local destinations. Results are cached for 30 seconds.</div>`;
