    const panel=document.createElement('section');panel.className='panel-card settings-card host-mount-card';panel.innerHTML=`<div class="panel-head"><div><h2>Host mounts</h2><p>Connect a host folder to the primary container or an app stack service. Mounts are read-only by default and apply on the next start.</p></div></div><div class="host-mount-list" data-host-mount-list></div><div class="host-mount-actions"><button class="button subtle" type="button" data-add-host-mount>+ Add mount</button><button class="button primary" type="button" data-save-host-mounts>Save mounts</button></div><p class="host-mount-foot">NFS and CIFS shares must already be mounted on the host. Check xattr support for apps that need it, such as OpenCloud.</p>`;grid.append(panel);
