    document.querySelector('#add-registry-login').onclick=()=>editRegistryLogin(null);
    document.querySelectorAll('[data-registry-replace]').forEach(button=>button.onclick=()=>editRegistryLogin(logins.find(item=>item.id===button.dataset.registryReplace)));
    document.querySelectorAll('[data-registry-test]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/registry-logins/${button.dataset.registryTest}/test`,{method:'POST',body:'{}'});toast('Registry login verified','success')}catch(e){toast(e.message,'error')}finally{button.disabled=false}});
    document.querySelectorAll('[data-registry-delete]').forEach(button=>button.onclick=async()=>{const item=logins.find(login=>login.id===button.dataset.registryDelete);if(!confirm(`Remove saved access for ${item?.registry||'this registry'}?`))return;try{await api(`/api/registry-logins/${button.dataset.registryDelete}`,{method:'DELETE'});toast('Registry login removed','success');await manageRegistryLogins()}catch(e){toast(e.message,'error')}});
