  function editRegistryLogin(existing){
    modal(`<div class="modal-heading"><div><div class="eyebrow">${existing?'REPLACE CREDENTIAL':'NEW CREDENTIAL'}</div><h2>${existing?'Replace registry login':'Add registry login'}</h2></div><button class="icon-button" data-close>×</button></div><form id="registry-login-form"><label>Registry hostname<input name="registry" required value="${esc(existing?.registry||'')}" placeholder="ghcr.io, registry.example.com:5000 or docker.io" ${existing?'readonly':''}><small>Image references are matched using Docker’s registry naming rules.</small></label><label>Username<input name="username" required autocomplete="username" value="${esc(existing?.username||'')}"></label><label>Password or access token<input name="secret" type="password" required autocomplete="new-password"></label><small>The credential is never returned by the API. Saving again replaces the credential for this registry.</small><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">${existing?'Replace login':'Save login'}</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelector('#registry-login-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await api('/api/registry-logins',{method:'POST',body:JSON.stringify({registry:form.get('registry'),username:form.get('username'),secret:form.get('secret')})});toast(existing?'Registry login replaced':'Registry login saved','success');await manageRegistryLogins()}catch(e){toast(e.message,'error')}};
  }
  async function manageRuneCatalogs(){
    let repositories=[],github={has_token:false};
    try{[repositories,github]=await Promise.all([api('/api/rune-repos'),api('/api/settings/github')])}catch(e){toast(e.message,'error');return}
    modal(`<div class="modal-heading"><div><div class="eyebrow">SAVED SOURCES</div><h2>Catalog repositories</h2></div><button class="icon-button" data-close>×</button></div><p class="muted-copy">Docklight contacts only repositories saved here. GitHub is the default host; other hosts must use HTTPS. Repository tokens are encrypted and used only for their saved repository.</p><div class="catalog-repo-list">${repositories.map(repo=>`<article class="catalog-repo-row"><div class="catalog-repo-copy"><b>${esc(repo.name)}</b><small>${esc(repo.host)} · ${esc(repo.repo)}${repo.path?`/${esc(repo.path)}`:''} · ${esc(repo.ref)}${repo.has_token?' · Token saved':''}</small></div><div class="catalog-repo-actions"><button class="button subtle" data-repo-browse="${esc(repo.id)}">Browse</button><button class="button subtle" data-repo-edit="${esc(repo.id)}">Edit</button><button class="button danger" data-repo-delete="${esc(repo.id)}">Remove</button></div></article>`).join('')||'<div class="files-empty">No catalog repositories saved yet.</div>'}</div><div class="catalog-settings"><h3>GitHub access token</h3><p class="muted-copy">Optional panel-wide token for GitHub API requests. A token saved on a specific repository takes priority.</p><form id="github-token-form"><label>Token<input type="password" name="token" autocomplete="new-password" placeholder="${github.has_token?'Saved · leave empty to keep it':'Optional'}"></label>${github.has_token?'<label class="checkline"><input type="checkbox" name="clear"> Remove saved GitHub token</label>':''}<button class="button subtle" type="submit">Save token settings</button></form></div><div class="modal-actions"><button class="button subtle" data-close>Close</button><button class="button primary" id="add-rune-repo">+ Add repository</button></div>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelector('#add-rune-repo').onclick=()=>editRuneRepo(null);
    document.querySelectorAll('[data-repo-browse]').forEach(button=>button.onclick=()=>browseRuneRepository(repositories.find(repo=>repo.id===button.dataset.repoBrowse),''));
    document.querySelectorAll('[data-repo-edit]').forEach(button=>button.onclick=()=>editRuneRepo(repositories.find(repo=>repo.id===button.dataset.repoEdit)));
    document.querySelectorAll('[data-repo-delete]').forEach(button=>button.onclick=async()=>{const repo=repositories.find(item=>item.id===button.dataset.repoDelete);if(!confirm(`Remove ${repo.name}? Installed templates keep their source record and will report that the source is gone.`))return;try{await api(`/api/rune-repos/${repo.id}`,{method:'DELETE'});toast('Catalog repository removed','success');await manageRuneCatalogs()}catch(e){toast(e.message,'error')}});
    document.querySelector('#github-token-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const token=form.get('clear')?'':(form.get('token')||'');try{await api('/api/settings/github',{method:'PUT',body:JSON.stringify({token:github.has_token&&!form.get('clear')&&!token?'••••••••':token})});toast('GitHub token settings saved','success');await manageRuneCatalogs()}catch(e){toast(e.message,'error')}};
  }
  function editRuneRepo(repo){
    const editing=Boolean(repo);
    modal(`<div class="modal-heading"><div><div class="eyebrow">${editing?'EDIT SOURCE':'NEW SOURCE'}</div><h2>${editing?'Edit catalog repository':'Add catalog repository'}</h2></div><button class="icon-button" data-close>×</button></div><form id="rune-repo-form"><label>Display name<input name="name" maxlength="80" required value="${esc(repo?.name||'')}" placeholder="Community templates"></label><label>Host <small>Leave blank for GitHub. Gitea and Forgejo require an HTTPS base URL.</small><input name="host" value="${esc(repo?.host==='github.com'?'':repo?.host||'')}" placeholder="https://git.example.com"></label><label>Repository <small>owner/name</small><input name="repo" required value="${esc(repo?.repo||'')}" placeholder="community/templates"></label><div class="two-fields"><label>Folder<input name="path" value="${esc(repo?.path||'')}" placeholder="catalog"></label><label>Branch or tag<input name="ref" value="${esc(repo?.ref||'main')}" required></label></div><label>Repository token<input name="token" type="password" autocomplete="new-password" placeholder="${repo?.has_token?'Saved · leave empty to keep it':'Optional'}"></label>${repo?.has_token?'<label class="checkline"><input name="clear_token" type="checkbox"> Clear saved token</label>':''}<small>Tokens stay encrypted on this panel and are used only for this repository’s host and repo.</small><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">${editing?'Save repository':'Add repository'}</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelector('#rune-repo-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);let token=form.get('token')||'';if(repo?.has_token&&!form.get('clear_token')&&!token)token='••••••••';if(form.get('clear_token'))token='';const payload={name:form.get('name'),host:form.get('host'),repo:form.get('repo'),path:form.get('path'),ref:form.get('ref'),token};try{await api(editing?`/api/rune-repos/${repo.id}`:'/api/rune-repos',{method:editing?'PUT':'POST',body:JSON.stringify(payload)});toast(editing?'Repository updated':'Repository added','success');await manageRuneCatalogs()}catch(e){toast(e.message,'error')}};
  }
  async function browseRuneRepository(repo,relativePath=''){
    if(!repo)return;
    let result;
    try{result=await api(`/api/rune-repos/${repo.id}/browse${relativePath?`?path=${encodeURIComponent(relativePath)}`:''}`)}catch(e){toast(e.message,'error');return}
    const entries=result.entries||[];
    modal(`<div class="modal-heading"><div><div class="eyebrow">${esc(repo.host)} · ${esc(repo.repo)} · ${esc(repo.ref)}</div><h2>Browse templates</h2></div><button class="icon-button" data-close>×</button></div><div class="catalog-browser-path">${esc(repo.path||'Repository root')}${relativePath?` / ${esc(relativePath)}`:''}</div><div class="catalog-browser">${relativePath?'<button class="catalog-entry folder" id="catalog-up">← Back to repository folder</button>':''}${entries.map(entry=>entry.type==='dir'?`<button class="catalog-entry folder" data-catalog-folder="${esc(entry.name)}"><span>▱</span><b>${esc(entry.name)}</b><small>Folder</small></button>`:`<div class="catalog-entry"><span>▤</span><b>${esc(entry.name)}</b><small>${entry.size?`${formatBytes(entry.size)} · `:''}YAML</small><button class="button primary" data-catalog-install="${esc(entry.path)}">Install</button></div>`).join('')||'<div class="files-empty">No YAML templates in this folder.</div>'}</div><div class="modal-actions"><button class="button subtle" data-close>Close</button></div>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelector('#catalog-up')?.addEventListener('click',()=>browseRuneRepository(repo,''));
    document.querySelectorAll('[data-catalog-folder]').forEach(button=>button.onclick=()=>browseRuneRepository(repo,relativePath?[relativePath,button.dataset.catalogFolder].join('/'):button.dataset.catalogFolder));
    document.querySelectorAll('[data-catalog-install]').forEach(button=>button.onclick=async()=>{try{const installed=await api(`/api/rune-repos/${repo.id}/install`,{method:'POST',body:JSON.stringify({path:button.dataset.catalogInstall})});closeModal();toast(`Installed ${installed.name} · v${installed.version}`,'success');await refresh();render()}catch(e){toast(e.message,'error')}});
  }
  async function checkRuneCatalogUpdates(){
    let result;
    try{result=await api('/api/gameskills/updates')}catch(e){toast(e.message,'error');return}
    const updates=result.updates||[],notes=result.notes||[];
    const updateRows=updates.map(update=>`<article class="catalog-repo-row"><div class="catalog-repo-copy"><b>${esc(update.name)}</b><small>v${update.installed_version} <span class="update-arrow">↑</span> v${update.available_version} · ${esc(update.source_host)} · ${esc(update.source_repo)}</small></div><div class="catalog-repo-actions"><a class="button subtle" href="${esc(update.download_url)}" target="_blank" rel="noreferrer">View source ↗</a><button class="button primary" data-update-apply="${esc(update.repository_id)}" data-update-path="${esc(update.path)}" data-update-ref="${esc(update.ref)}">Apply update</button></div></article>`).join('')||'<div class="files-empty">No newer template versions found.</div>';
    const noteRows=notes.map(note=>`<p>${esc(note)}</p>`).join('');
    const noteBlock=notes.length?`<section class="catalog-notes"><h3>Catalog notes</h3>${noteRows}</section>`:'';
    modal(`<div class="modal-heading"><div><div class="eyebrow">CATALOG CHECK</div><h2>Template updates</h2></div><button class="icon-button" data-close>×</button></div><p class="muted-copy">The check only lists available versions. Applying an update replaces the stored YAML used by new and existing servers.</p><div class="catalog-update-list">${updateRows}</div>${noteBlock}<div class="modal-actions"><button class="button subtle" data-close>Close</button></div>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelectorAll('[data-update-apply]').forEach(button=>button.onclick=async()=>{try{const updated=await api(`/api/rune-repos/${button.dataset.updateApply}/install`,{method:'POST',body:JSON.stringify({path:button.dataset.updatePath,ref:button.dataset.updateRef})});closeModal();toast(`Updated ${updated.name} to v${updated.version}`,'success');await refresh();render();checkRuneCatalogUpdates()}catch(e){toast(e.message,'error')}});
  }
