  async function newServerModal(runeID, realmID){
    let options=state.runes;
    if(!options.length)await refresh();
    options=state.runes;
    if(!options.length){toast('No server templates are available for your account','error');return;}
    const selected=runeID||options[0]?.id;
    const selectedRune=options.find(r=>r.id===selected);
    const canDefault=r=>state.user.role==='admin'||Boolean(r?.can_create_default);
    const realmOptions=state.realms.filter(r=>r.can_create);
    let initialRealm=realmID|| (canDefault(selectedRune)?'':realmOptions[0]?.id||'');
    const variableForm=(r)=>(r?.variables||[]).map(v=>{const value=v.secret?'':(v.default??'');return `<label>${esc(v.name||v.key)}${v.required?'<sup>*</sup>':''}${v.hint?`<small>${esc(v.hint)}</small>`:''}${v.type==='select'?`<select name="${esc(v.key)}">${(v.options||[]).map(o=>`<option ${o===String(value)?'selected':''}>${esc(o)}</option>`).join('')}</select>`:v.type==='bool'?`<select name="${esc(v.key)}"><option value="true" ${String(value)==='true'?'selected':''}>Enabled</option><option value="false" ${String(value)==='false'?'selected':''}>Disabled</option></select>`:`<div class="input-with-button"><input name="${esc(v.key)}" type="${v.secret?'password':'text'}" value="${esc(value)}" placeholder="${v.secret?'Required secret value':esc(value)}" ${v.required?'required':''}>${v.secret?`<button type="button" data-generate="${esc(v.key)}" title="Generate a secure value">⤨</button>`:''}</div>`}</label>`}).join('');
    const buildRealmOptions=(r,preferred)=>`${canDefault(r)?`<option value="" ${preferred===''?'selected':''}>Automatic · ${esc(r.category||'Default')}</option>`:''}${realmOptions.map(x=>`<option value="${esc(x.id)}" ${preferred===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}`;
    const draw=async id=>{try{const r=await api(`/api/gameskills/${id}`);document.querySelector('#rune-fields').innerHTML=variableForm(r)||'<p class="muted-copy">This template has no settings to configure.</p>';const selector=document.querySelector('#realm-select');const previous=selector.value;const chosen=realmOptions.some(x=>x.id===previous)?previous:(canDefault(options.find(x=>x.id===id))?'':realmOptions[0]?.id||'');selector.innerHTML=buildRealmOptions(options.find(x=>x.id===id),chosen);selector.value=chosen;document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=()=>{const input=document.querySelector(`[name="${CSS.escape(b.dataset.generate)}"]`);const bytes=crypto.getRandomValues(new Uint8Array(24));const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%_-';input.value=Array.from(bytes,x=>alphabet.charAt(x%alphabet.length)).join('');});}catch(e){toast(e.message,'error')}};
    modal(`<div class="modal-heading"><div><div class="eyebrow">NEW DEPLOYMENT</div><h2>Create a server</h2></div><button class="icon-button" data-close>×</button></div><form id="create-server-form"><label>Server name<input name="name" required maxlength="80" placeholder="My server"></label><label>Template<select name="gameskill_id" id="rune-select">${options.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.name)} · ${esc(r.category||'Default')}</option>`).join('')}</select></label><label>Realm<select name="realm_id" id="realm-select">${buildRealmOptions(selectedRune,initialRealm)}</select><small>New realms are created automatically by template category when you use automatic placement.</small></label><div id="rune-fields"></div><div class="two-fields"><label>CPU limit <small>cores, 0 for unlimited</small><input name="cpu_limit" type="number" min="0" max="64" step="0.1" value="0"></label><label>Memory limit <small>MB, 0 for unlimited</small><input name="memory_limit_mb" type="number" min="0" value="0"></label></div><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary" type="submit">Create server <span>→</span></button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);
    document.querySelector('#rune-select').onchange=e=>draw(e.target.value);
    await draw(selected);
    document.querySelector('#create-server-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget),env={};const currentRune=await api(`/api/gameskills/${data.get('gameskill_id')}`);for(const v of currentRune.variables||[]){const value=data.get(v.key);if(value!==null&&value!=='')env[v.key]=value;}try{const s=await api('/api/servers',{method:'POST',body:JSON.stringify({name:data.get('name'),gameskill_id:data.get('gameskill_id'),realm_id:data.get('realm_id')||'',env,cpu_limit:Number(data.get('cpu_limit')),memory_limit_mb:Number(data.get('memory_limit_mb'))})});closeModal();await refresh();state.selected=state.servers.find(x=>x.id===s.id);render();toast('Server created. Run install to continue.','success')}catch(err){toast(err.message,'error')}};
  }

  async function renderRealms(){
    const view=document.querySelector('#view');
    if(state.user.role!=='admin'){view.innerHTML='<div class="page-heading"><h1>Not available</h1></div>';return;}
    const renderMembers=(realmID)=>state.servers.filter(server=>(server.realm_id||'')===realmID).map(server=>`<label class="realm-member"><span><b>${esc(server.name)}</b><small>${esc(server.gameskill_id)}</small></span><select data-move-server="${esc(server.id)}" aria-label="Move ${esc(server.name)} to realm"><option value="">Unassigned</option>${state.realms.map(item=>`<option value="${esc(item.id)}" ${item.id===realmID?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label>`).join('')||'<p class="muted-copy">No servers in this realm yet.</p>';
    const realmCards=state.realms.map((realm,index)=>`<section class="panel-card realm-admin-card"><form data-realm-form="${esc(realm.id)}"><div class="realm-admin-fields"><label>Realm name<input name="name" maxlength="80" required value="${esc(realm.name)}"></label><label>Description<input name="description" maxlength="500" value="${esc(realm.description||'')}"></label></div><div class="realm-admin-actions"><button class="button subtle" type="submit">Save</button><button class="button subtle" type="button" data-realm-up="${index}" ${index===0?'disabled':''} aria-label="Move ${esc(realm.name)} up">↑</button><button class="button subtle" type="button" data-realm-down="${index}" ${index===state.realms.length-1?'disabled':''} aria-label="Move ${esc(realm.name)} down">↓</button><button class="button danger" type="button" data-realm-delete="${esc(realm.id)}">Delete</button></div></form><div class="realm-members"><div class="eyebrow">SERVERS · ${realm.server_count}</div>${renderMembers(realm.id)}</div></section>`).join('');
    const unassigned=state.servers.some(server=>!server.realm_id);
    view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ORGANIZE YOUR HOST</div><h1>Realms</h1><p>Group servers, control creation access, and keep each person’s collapsed sections private.</p></div></div><section class="panel-card realm-create-card"><div><h2>Create a realm</h2><p>Templates place new servers in a category realm unless a different realm is selected.</p></div><form id="realm-create-form"><label>Realm name<input name="name" maxlength="80" required placeholder="Production"></label><label>Description<input name="description" maxlength="500" placeholder="Public-facing services"></label><button class="button primary" type="submit">+ Add realm</button></form></section><div class="realm-admin-list">${realmCards||'<section class="panel-card files-empty">No realms yet. Create one above to organize servers.</section>'}${unassigned?`<section class="panel-card realm-admin-card"><div class="eyebrow">UNASSIGNED</div><div class="realm-members">${renderMembers('')}</div></section>`:''}</div>`;
    view.querySelector('#realm-create-form').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget);try{await api('/api/realms',{method:'POST',body:JSON.stringify({name:data.get('name'),description:data.get('description')})});await refresh();renderRealms();toast('Realm created','success')}catch(err){toast(err.message,'error')}};
    view.querySelectorAll('[data-realm-form]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const data=new FormData(form);try{await api(`/api/realms/${form.dataset.realmForm}`,{method:'PUT',body:JSON.stringify({name:data.get('name'),description:data.get('description')})});await refresh();renderRealms();toast('Realm saved','success')}catch(err){toast(err.message,'error')}});
    view.querySelectorAll('[data-realm-delete]').forEach(button=>button.onclick=async()=>{const realm=state.realms.find(item=>item.id===button.dataset.realmDelete);if(!confirm(`Delete ${realm?.name||'this realm'}? Its servers will be left unassigned and realm permissions removed.`))return;try{await api(`/api/realms/${button.dataset.realmDelete}`,{method:'DELETE'});await refresh();renderRealms();toast('Realm deleted','success')}catch(err){toast(err.message,'error')}});
    const reorder=async(index,delta)=>{const ids=state.realms.map(realm=>realm.id),target=index+delta;[ids[index],ids[target]]=[ids[target],ids[index]];try{await api('/api/realms/reorder',{method:'POST',body:JSON.stringify({ids})});await refresh();renderRealms()}catch(err){toast(err.message,'error')}};
    view.querySelectorAll('[data-realm-up]').forEach(button=>button.onclick=()=>reorder(Number(button.dataset.realmUp),-1));
    view.querySelectorAll('[data-realm-down]').forEach(button=>button.onclick=()=>reorder(Number(button.dataset.realmDown),1));
    view.querySelectorAll('[data-move-server]').forEach(select=>select.onchange=async()=>{try{await api(`/api/servers/${select.dataset.moveServer}/realm`,{method:'PUT',body:JSON.stringify({realm_id:select.value})});await refresh();renderRealms();toast('Server moved','success')}catch(err){toast(err.message,'error');await refresh();renderRealms()}});
  }

  async function renderUsers(){const v=document.querySelector('#view');if(state.user.role!=='admin'){v.innerHTML='<div class="page-heading"><h1>Not available</h1></div>';return;}try{state.users=await api('/api/users')}catch(e){v.innerHTML=`<h1>Error</h1><p>${esc(e.message)}</p>`;return;}v.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Users & access</h1><p>Give each person access only to the servers they need.</p></div><button class="button primary" id="add-user">+ Add user</button></div><div class="panel-card users-table"><div class="user-table-head"><span>USER</span><span>ROLE</span><span>2FA</span><span>STATUS</span><span></span></div>${state.users.map(u=>`<div class="user-row"><div><span class="avatar small">${esc(u.username[0].toUpperCase())}</span><b>${esc(u.username)}</b></div><span><span class="role-badge">${esc(u.role)}</span></span><span>${u.totp_enabled?'<span class="good-text">Enabled</span>':'<span class="muted-copy">Not set</span>'}</span><span>${u.disabled?'<span class="status-badge bad"><i></i>Disabled</span>':'<span class="status-badge good"><i></i>Active</span>'}</span><button class="button subtle" data-user-edit="${esc(u.id)}">Manage</button></div>`).join('')}</div>`;document.querySelector('#add-user').onclick=()=>createUserModal();v.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>manageUser(b.dataset.userEdit));}
  function createUserModal(){modal(`<div class="modal-heading"><div><div class="eyebrow">NEW ACCOUNT</div><h2>Add a user</h2></div><button class="icon-button" data-close>×</button></div><form id="new-user-form"><label>Username<input name="username" required maxlength="64"></label><label>Account email <small>Used only for one-time password reset links.</small><input name="email" type="email" autocomplete="email" maxlength="254"></label><label>Temporary password<input name="password" type="password" minlength="12" autocomplete="new-password" required><small>At least 12 characters. Share it with the user privately.</small></label><label>Role<select name="role"><option value="user">User · scoped access</option><option value="admin">Administrator · full access</option></select></label><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">Create user</button></div></form>`);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelector('#new-user-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/users',{method:'POST',body:JSON.stringify(f)});closeModal();renderUsers();toast('User created','success')}catch(err){toast(err.message,'error')}};}
  async function manageUser(id){
    const user=state.users.find(x=>x.id===id);
    let grants=[];
    try{grants=(await api(`/api/users/${id}/permissions`)).grants||[]}catch{}
    const realms=state.realms,servers=state.servers;
    const realmPermissions=['server.view','server.control','server.console','server.files','server.backup','server.schedule','server.create','server.delete'];
    const serverPermissions=realmPermissions.filter(permission=>permission!=='server.create');
    const globalGrant=grants.find(grant=>grant.scope_type==='global'&&grant.scope_id==='');
    modal(`<div class="modal-heading"><div><div class="eyebrow">ACCOUNT & PERMISSIONS</div><h2>${esc(user.username)}</h2></div><button class="icon-button" data-close>×</button></div><div class="user-manage"><label>Role<select id="edit-role"><option value="user" ${user.role==='user'?'selected':''}>User</option><option value="admin" ${user.role==='admin'?'selected':''}>Administrator</option></select></label><label>New password <small>Leave empty to keep the current password</small><input id="edit-password" type="password" minlength="12" autocomplete="new-password"></label><label class="checkline"><input id="edit-disabled" type="checkbox" ${user.disabled?'checked':''}> Disable this account</label><div class="grant-heading"><h3>Global grants</h3><span>Applies to every server and template</span></div><div class="grant-row"><div><b>Entire Docklight instance</b><small>Use with care; these rights cover future resources too.</small></div><div class="grant-checks">${realmPermissions.map(permission=>`<label title="${permission}"><input type="checkbox" data-global-grant value="${permission}" ${globalGrant?.permissions?.includes(permission)?'checked':''}><span>${permission.replace('server.','')}</span></label>`).join('')}</div></div><div class="grant-heading"><h3>Realm grants</h3><span>Includes future servers in that realm</span></div><div class="grant-list">${realms.map(realm=>{const old=grants.find(g=>g.scope_type==='realm'&&g.scope_id===realm.id);return `<div class="grant-row"><div><b>${esc(realm.name)}</b><small>${esc(realm.description||'Realm-wide access')}</small></div><div class="grant-checks">${realmPermissions.map(permission=>`<label title="${permission}"><input type="checkbox" data-realm-grant="${esc(realm.id)}" value="${permission}" ${old?.permissions?.includes(permission)?'checked':''}><span>${permission.replace('server.','')}</span></label>`).join('')}</div></div>`}).join('')||'<p class="muted-copy">Create a realm before assigning realm-wide access.</p>'}</div><div class="grant-heading"><h3>Template grants</h3><span>Applies to servers created from a template</span></div><div class="grant-list">${state.runes.map(template=>{const old=grants.find(g=>g.scope_type==='gameskill'&&g.scope_id===template.id);return `<div class="grant-row"><div><b>${esc(template.name)}</b><small>${esc(template.category||'Default')}</small></div><div class="grant-checks">${realmPermissions.map(permission=>`<label title="${permission}"><input type="checkbox" data-template-grant="${esc(template.id)}" value="${permission}" ${old?.permissions?.includes(permission)?'checked':''}><span>${permission.replace('server.','')}</span></label>`).join('')}</div></div>`}).join('')||'<p class="muted-copy">No templates are available.</p>'}</div><div class="grant-heading"><h3>Server grants</h3><span>Applies to selected servers only</span></div><div class="grant-list">${servers.map(server=>{const old=grants.find(g=>g.scope_type==='server'&&g.scope_id===server.id);return `<div class="grant-row"><div><b>${esc(server.name)}</b><small>${esc(server.gameskill_id)}</small></div><div class="grant-checks">${serverPermissions.map(permission=>`<label title="${permission}"><input type="checkbox" data-server-grant="${esc(server.id)}" value="${permission}" ${old?.permissions?.includes(permission)?'checked':''}><span>${permission.replace('server.','')}</span></label>`).join('')}</div></div>`}).join('')||'<p class="muted-copy">Create a server before assigning server-specific access.</p>'}</div><div class="modal-actions"><button class="button danger" id="delete-user">Delete user</button><button class="button primary" id="save-user">Save account & access</button></div></div>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    document.querySelector('#edit-role').closest('label').insertAdjacentHTML('afterend',`<label>Account email <small>Used only for one-time password reset links.</small><input id="edit-email" type="email" maxlength="254" autocomplete="email" value="${esc(user.email||'')}"></label>`);
    document.querySelector('#save-user').onclick=async()=>{
      const role=document.querySelector('#edit-role').value,email=document.querySelector('#edit-email').value,password=document.querySelector('#edit-password').value,disabled=document.querySelector('#edit-disabled').checked;
      try{
        await api(`/api/users/${id}`,{method:'PUT',body:JSON.stringify({role,email,password,disabled})});
        if(id===state.user.id){closeModal();state.user=null;renderLogin();toast('Your account was updated. Sign in again.','success');return;}
        const rows=[];
        const globalPermissions=Array.from(document.querySelectorAll('[data-global-grant]:checked'),box=>box.value);
        if(globalPermissions.length)rows.push({scope_type:'global',scope_id:'',permissions:globalPermissions});
        for(const [selector,scopeType,field] of [['[data-realm-grant]','realm','realmGrant'],['[data-template-grant]','gameskill','templateGrant'],['[data-server-grant]','server','serverGrant']]){
          const buckets={};document.querySelectorAll(selector).forEach(box=>{const scope=box.dataset[field];(buckets[scope] ||= []).push(box.value)});
          rows.push(...Object.entries(buckets).filter(([,permissions])=>permissions.length).map(([scope,permissions])=>({scope_type:scopeType,scope_id:scope,permissions})));
        }
        await api(`/api/users/${id}/permissions`,{method:'PUT',body:JSON.stringify({grants:rows})});
        closeModal();await renderUsers();toast('Account and permissions updated','success');
      }catch(error){toast(error.message,'error')}
    };
    document.querySelector('#delete-user').onclick=async()=>{if(!confirm(`Delete user ${user.username}?`))return;try{await api(`/api/users/${id}`,{method:'DELETE'});closeModal();await renderUsers();toast('User deleted','success')}catch(error){toast(error.message,'error')}};
  }
  async function renderAudit(){
    const v=document.querySelector('#view');
    try{
      const rows=await api('/api/audit');
      v.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ACCOUNTABILITY</div><h1>Audit history</h1><p>Administrative actions recorded by the panel.</p></div><button class="button subtle" id="activity-digest" type="button">Summarize activity</button></div><section class="panel-card assistant-digest hidden" id="activity-digest-card"><div class="panel-head"><div><h2>Activity digest</h2><p>Uses up to 200 structured events. Audit detail text is excluded.</p></div></div><div class="assistant-digest-state" id="activity-digest-state" role="status"></div><pre class="assistant-digest-result hidden" id="activity-digest-result"></pre></section><div class="panel-card audit-table"><div class="audit-head"><span>TIME</span><span>ACTOR</span><span>ACTION</span><span>TARGET</span><span>DETAIL</span></div>${rows.map(x=>`<div class="audit-row"><span>${esc(x.at)}</span><span>${esc(x.username||'system')}</span><code>${esc(x.action)}</code><span>${esc(x.target_id||'—')}</span><span>${esc(x.detail||'—')}</span></div>`).join('')||'<div class="files-empty">No actions recorded yet.</div>'}</div>`;
      v.querySelector('#activity-digest').onclick=async event=>{const button=event.currentTarget,card=v.querySelector('#activity-digest-card'),stateEl=v.querySelector('#activity-digest-state'),resultEl=v.querySelector('#activity-digest-result');card.classList.remove('hidden');button.disabled=true;stateEl.textContent='Summarizing recent activity…';resultEl.classList.add('hidden');resultEl.textContent='';try{const result=await api('/api/admin-log/digest',{method:'POST',body:'{}'});resultEl.textContent=result.text||'';resultEl.classList.remove('hidden');stateEl.textContent=`Reviewed ${fmt(result.events_reviewed)} events.`}catch(error){stateEl.textContent=error.message}finally{button.disabled=false}};
    }catch(e){v.innerHTML=`<div class="page-heading"><h1>Audit history</h1><p class="error-text">${esc(e.message)}</p></div>`}
  }
  async function renderFleetAssistant(){
    const view=document.querySelector('#view');
    view.innerHTML='<div class="page-heading"><div><div class="eyebrow">READ-ONLY OPERATIONS</div><h1>Advisory</h1><p>Ask questions about the servers you can access. Docklight will not run actions from this conversation.</p></div><span class="status-badge muted"><i></i>SCOPED TO YOUR ACCESS</span></div><div class="fleet-assistant-layout"><section class="panel-card fleet-assistant-main"><div class="panel-head"><div><h2>Fleet conversation</h2><p id="fleet-assistant-summary">Loading Advisory settings and visible servers…</p></div><button class="button subtle" type="button" id="fleet-chat-clear">New chat</button></div><div class="assistant-chat-history" id="fleet-chat-history" aria-live="polite" aria-relevant="additions text"></div><div id="fleet-chat-state" class="assistant-digest-state" role="status"></div><form class="assistant-chat-form" id="fleet-chat-form"><label>Question<textarea name="question" rows="3" maxlength="2000" required placeholder="What needs attention across my servers?"></textarea></label><div id="fleet-log-controls" class="fleet-log-controls" hidden><label>Optional log search · one server at a time<select name="log_server_id"><option value="">Choose a visible server</option></select></label><label>Matching text<input name="log_query" maxlength="160" placeholder="e.g. connection refused"><small>Docklight filters recent lines locally. Matching lines are limited and redacted, but may still include player chat, IP addresses, or other private content.</small></label></div><div class="fleet-chat-foot"><small>Conversation history stays in this browser tab and is limited to the latest ten messages. Advisory is read-only.</small><button class="button primary" type="submit" id="fleet-chat-send">Ask Advisory <span>→</span></button></div></form></section><aside class="panel-card fleet-assistant-note"><div class="eyebrow">DATA SCOPE</div><h2 id="fleet-scope-title">Loading…</h2><p id="fleet-scope-copy"></p><div class="assistant-note-row"><b>Access</b><p>Only servers this account can view are included. Hidden servers are left out before data reaches the provider.</p></div><div class="assistant-note-row"><b>Provider</b><p id="fleet-provider-copy"></p></div><div class="assistant-note-row"><b>Privacy</b><p>Questions and answers are not saved as transcripts. Audit records contain summary counts only. Never paste passwords, API keys, or other credentials.</p></div><div id="fleet-admin-hint" class="assistant-note-row hidden"><b>Advisory is off</b><p>An administrator can configure it under Manage → Assistant.</p></div></aside></div><section class="panel-card assistant-digest fleet-proactive-history"><div class="panel-head"><div><h2>Recent observations</h2><p>Proactive Advisory history visible to this account.</p></div><button class="button subtle" type="button" id="fleet-events-refresh">Refresh</button></div><div id="fleet-proactive-event-list" class="assistant-proactive-list" aria-live="polite"></div></section>';
    let status, servers;
    try{
      [status,servers]=await Promise.all([api('/api/ai/status'),api('/api/servers')]);
    }catch(error){
      if(view.isConnected){view.querySelector('#fleet-assistant-summary').textContent=error.message;view.querySelector('#fleet-chat-state').textContent='Advisory is unavailable until settings and server access can be loaded.';view.querySelectorAll('#fleet-chat-form input,#fleet-chat-form select,#fleet-chat-form textarea,#fleet-chat-form button').forEach(control=>control.disabled=true);}
      return;
    }
    if(!view.isConnected||state.route!=='advisory')return;
    const level=Math.max(0,Math.min(2,Number(status.chat_data_level)||0));
    const host=status.llm_host||'configured provider';
    view.querySelector('#fleet-assistant-summary').textContent=status.enabled?'Answers use only the servers visible to this account.':'Advisory is currently disabled.';
    view.querySelector('#fleet-scope-title').textContent='Level '+level;
    view.querySelector('#fleet-scope-copy').textContent=level===0?'Visible server state and relevant Docklight guides.':level===1?'Level 0 plus 24-hour resource summaries, backup summaries, and scheduled outcomes.': 'Level 1 plus a separate search of matching lines from one selected server.';
    view.querySelector('#fleet-provider-copy').textContent='Configured provider host: '+host+(status.llm_local?' (local or private-network endpoint).':' (hosted endpoint).');
    view.querySelector('#fleet-admin-hint').classList.toggle('hidden',Boolean(status.enabled));
    const logControls=view.querySelector('#fleet-log-controls');
    logControls.hidden=level<2;
    const serverSelect=view.querySelector('[name="log_server_id"]');
    for(const server of servers){
      const option=document.createElement('option');
      option.value=server.id;
      option.textContent=server.name;
      serverSelect.append(option);
    }
    if(level===2){
      const warning=document.createElement('small');
      warning.className='fleet-log-consent-note';
      warning.textContent=status.llm_local?'Matching redacted lines are sent to the configured local/private-network provider.':'Each hosted-provider log search asks you to confirm the current provider host before sending matching redacted lines.';
      logControls.append(warning);
    }
    const thread=view.querySelector('#fleet-chat-history');
    const form=view.querySelector('#fleet-chat-form');
    const sendButton=view.querySelector('#fleet-chat-send');
    const stateEl=view.querySelector('#fleet-chat-state');
    const conversation=[];
    let pending=null;
    const appendMessage=(role,text,detail)=>{
      const item=document.createElement('article');
      item.className='assistant-chat-message '+role;
      const label=document.createElement('b');
      label.textContent=role==='user'?'You':'Docklight Advisory';
      const body=document.createElement('pre');
      body.textContent=text;
      item.append(label,body);
      if(detail){const meta=document.createElement('small');meta.textContent=detail;item.append(meta)}
      thread.append(item);
      thread.scrollTop=thread.scrollHeight;
      return {item,body};
    };
    const resetThread=()=>{
      if(fleetChatSocket){fleetChatSocket.close();fleetChatSocket=null;}
      conversation.length=0;
      thread.replaceChildren();
      appendMessage('assistant','Ask about the servers you can access. I can summarize their state and permitted operational history, but I cannot change them.','');
      stateEl.textContent='';
    };
    resetThread();
    view.querySelector('#fleet-chat-clear').onclick=()=>{
      if(pending){stateEl.textContent='Wait for the current answer before starting a new conversation.';return}
      resetThread();
    };
    const finishFailure=(request,message)=>{
      if(pending!==request)return;
      pending=null;
      clearTimeout(request.timeout);
      request.loading.body.textContent='I could not complete that request.';
      stateEl.textContent=message||'The Advisory connection closed. Try again.';
      sendButton.disabled=false;
    };
    const finishAnswer=(request,message)=>{
      if(pending!==request)return;
      pending=null;
      clearTimeout(request.timeout);
      request.loading.body.textContent=message.text||'No answer was returned.';
      const meta=message.meta||{};
      const detail='Used '+(meta.included_server_count||0)+' of '+(meta.visible_server_count||0)+' visible servers · '+(meta.docs_used||0)+' guide excerpts'+(meta.log_lines_included?' · '+meta.log_lines_included+' matching log lines':'');
      const metaNode=document.createElement('small');
      metaNode.textContent=detail;
      request.loading.item.append(metaNode);
      conversation.push({role:'user',content:request.question},{role:'assistant',content:message.text||''});
      if(conversation.length>10)conversation.splice(0,conversation.length-10);
      stateEl.textContent='Answer ready. Conversation history is held only in this browser tab.';
      sendButton.disabled=false;
      form.elements.question.focus();
    };
    const connect=()=>new Promise((resolve,reject)=>{
      if(fleetChatSocket&&fleetChatSocket.readyState===WebSocket.OPEN){resolve(fleetChatSocket);return}
      const scheme=location.protocol==='https:'?'wss://':'ws://';
      const socket=new WebSocket(scheme+location.host+'/api/ai/chat/ws');
      fleetChatSocket=socket;
      let opened=false;
      const connectTimeout=setTimeout(()=>{if(!opened){socket.close();reject(new Error('Timed out connecting to Advisory.'))}},15000);
      socket.onopen=()=>{opened=true;clearTimeout(connectTimeout);resolve(socket)};
      socket.onerror=()=>{if(!opened){clearTimeout(connectTimeout);reject(new Error('Could not connect to Advisory.'))}};
      socket.onclose=()=>{
        if(fleetChatSocket===socket)fleetChatSocket=null;
        if(!opened){clearTimeout(connectTimeout);reject(new Error('Could not connect to Advisory.'))}
        if(pending&&state.route==='advisory')finishFailure(pending,'The Advisory connection closed. Try again.');
      };
      socket.onmessage=event=>{
        let message;
        try{message=JSON.parse(event.data)}catch{if(pending)finishFailure(pending,'Advisory returned an unreadable response.');return}
        if(!pending)return;
        if(message.type==='error'){finishFailure(pending,message.error);return}
        if(message.type==='answer')finishAnswer(pending,message);
      };
    });
    form.onsubmit=async event=>{
      event.preventDefault();
      if(!status.enabled){stateEl.textContent='An administrator must enable Advisory before you can ask a question.';return}
      if(pending)return;
      const question=form.elements.question.value.trim();
      const logServerID=form.elements.log_server_id?.value||'';
      const logQuery=form.elements.log_query?.value.trim()||'';
      if(!question)return;
      if(Boolean(logServerID)!==Boolean(logQuery)){stateEl.textContent='Choose one visible server and enter matching text together.';return}
      if(logQuery&&level<2){stateEl.textContent='An administrator has not enabled log searches in the data scope.';return}
      let confirmed=false;
      if(logQuery&&!status.llm_local){
        confirmed=window.confirm('Send matching locally redacted log lines to '+host+'? Player chat, IP addresses, and other private text may still be present.');
        if(!confirmed){stateEl.textContent='Log search cancelled. No log lines were sent.';return}
      }
      appendMessage('user',question,'');
      const loading=appendMessage('assistant','Connecting to Advisory…','');
      sendButton.disabled=true;
      stateEl.textContent='Waiting for Advisory…';
      const request={question,loading,timeout:null};
      pending=request;
      request.timeout=setTimeout(()=>{if(pending===request){finishFailure(request,'Advisory took too long to respond. Try again.');if(fleetChatSocket){fleetChatSocket.close();fleetChatSocket=null}}},150000);
      const payload=JSON.stringify({question,history:conversation.slice(-10),log_server_id:logServerID,log_query:logQuery,confirm_external_logs:confirmed,confirm_external_host:confirmed?host:''});
      try{
        const socket=await connect();
        if(pending!==request)return;
        request.loading.body.textContent='Thinking…';
        socket.send(payload);
      }catch(error){finishFailure(request,error.message)}
    };
    if(!status.enabled){form.querySelectorAll('input,select,textarea,button').forEach(control=>control.disabled=true);view.querySelector('#fleet-chat-clear').disabled=false;view.querySelector('#fleet-admin-hint').classList.remove('hidden');}
    const refreshEvents=async()=>{
      try{const result=await api('/api/ai/proactive-events');if(view.isConnected)renderAssistantProactiveEvents(view,result.events||[],Number(status.proactive_level)||0,refreshEvents)}
      catch(error){const list=view.querySelector('#fleet-proactive-event-list');if(view.isConnected&&list)list.textContent=error.message}
    };
    view.querySelector('#fleet-events-refresh').onclick=refreshEvents;
    await refreshEvents();
    if(!servers.length){stateEl.textContent='No servers are currently visible to this account. Ask an administrator for server access.';}
  }
  function renderAssistantProactiveEvents(view,events,level,refresh){
    const list=view.querySelector('#fleet-proactive-event-list');
    if(!list)return;
    list.replaceChildren();
    if(!events.length){const empty=document.createElement('div');empty.className='files-empty';empty.textContent=level?'No recent proactive observations.':'Proactive monitoring is off. An administrator can configure it under Manage → Assistant.';list.append(empty);return}
    for(const event of events){
      const card=document.createElement('article');card.className='assistant-proactive-event';
      const heading=document.createElement('div');heading.className='assistant-proactive-heading';
      const title=document.createElement('b');title.textContent=event.server_name+' · '+String(event.trigger||'observation').replaceAll('_',' ');
      const stamp=document.createElement('small');stamp.textContent=event.created_at||'';
      heading.append(title,stamp);
      const summary=document.createElement('p');summary.textContent=event.summary||'Advisory detected an operational observation.';
      const explanation=document.createElement('p');explanation.className='assistant-proactive-explanation';explanation.textContent=event.explanation||'Advisory is preparing an explanation.';
      const body=document.createElement('div');body.className='assistant-proactive-body';body.append(summary,explanation);
      if(event.suggested_action&&event.suggested_action!=='none'){
        const suggestion=document.createElement('p');suggestion.className='assistant-proactive-suggestion';suggestion.textContent='Suggested action: '+String(event.suggested_action).replaceAll('_',' ')+(event.suggestion_reason?' · '+event.suggestion_reason:'');
        body.append(suggestion);
        if(event.applied){const applied=document.createElement('small');applied.className='assistant-proactive-applied';applied.textContent='Safe automatic fix applied';body.append(applied)}
        else if(event.apply_status==='proposal'){const note=document.createElement('small');note.className='assistant-proactive-proposal';note.textContent='No change was made. Start, stop, restart, and safe restart can be requested separately through the confirmed Actions flow.';body.append(note)}
      }
      const actions=document.createElement('div');actions.className='assistant-proactive-actions';
      const dismiss=document.createElement('button');dismiss.className='button subtle';dismiss.type='button';dismiss.textContent='Dismiss';
      dismiss.onclick=async()=>{dismiss.disabled=true;try{await api('/api/ai/proactive-events/'+encodeURIComponent(event.id),{method:'DELETE'});await refresh()}catch(error){dismiss.disabled=false;toast(error.message,'error')}};
      actions.append(dismiss);
      card.append(heading,body,actions);
      list.append(card);
    }
  }
