        proactivePanel.innerHTML='<div class="panel-head"><div><h2>Proactive monitoring</h2><p>Review confirmed incidents and resource signals, then ask Advisory for a cautious explanation.</p></div><span class="status-badge '+(proactiveLevel?'good':'muted')+'"><i></i>'+(['OFF','EXPLAIN','PROPOSE','SAFE AUTO-FIX'][proactiveLevel]||'OFF')+'</span></div><form id="assistant-proactive-form"><label>Monitoring level<select name="level"><option value="0">0 · Off</option><option value="1">1 · Explain observations</option><option value="2">2 · Explain and suggest an action</option><option value="3">3 · Apply a narrow safe fix</option></select></label><fieldset class="proactive-trigger-fieldset"><legend>Watch for</legend><div class="proactive-trigger-grid"></div></fieldset><div class="assistant-note-row"><p>Level 3 requires Actions to be enabled. It can restart a confirmed crashed server or raise its memory limit after exit code 137 when fresh host metrics show enough headroom. Memory increases are capped; no more than three automatic fixes run per server in 30 minutes. Other suggestions never run automatically.</p></div><div id="assistant-proactive-state" class="assistant-test-result" role="status"></div><div class="form-actions"><button class="button subtle" type="submit">Save monitoring settings</button></div></form>';
