        for(const [value,labelText] of triggerNames){const label=document.createElement('label');label.className='checkline';const box=document.createElement('input');box.type='checkbox';box.name='triggers';box.value=value;box.checked=proactiveSelected.has(value);const labelTextNode=document.createElement('span');labelTextNode.textContent=labelText;label.append(box,labelTextNode);triggerGrid.append(label)}
        proactiveForm.onsubmit=async event=>{event.preventDefault();const button=proactiveForm.querySelector('button[type="submit"]'),stateEl=proactiveForm.querySelector('#assistant-proactive-state');button.disabled=true;stateEl.textContent='Saving proactive monitoring settings…';try{const triggers=Array.from(proactiveForm.querySelectorAll('[name="triggers"]:checked'),box=>box.value);await api('/api/ai/proactive-settings',{method:'PUT',body:JSON.stringify({level:Number(proactiveForm.elements.level.value),triggers})});toast('Proactive monitoring settings saved','success');await renderAssistant()}catch(error){stateEl.textContent=error.message}finally{button.disabled=false}};
