        try{const digest=await api('/api/ai/health-digest',{method:'POST',body:'{}'});result.textContent=digest.text;result.classList.remove('hidden');status.textContent=`Generated ${new Date(digest.generated_at).toLocaleString()}`}
        catch(error){status.textContent=error.message;toast(error.message,'error')}
